fprintf('min de u h(u) en [-1.5, 1.5]: %.3g  (&gt;= 0: pasivo)\n', min(v.*h(v)));
v1 = fzero(dh, [0.1 0.4]);  v2 = fzero(dh, [0.4 0.9]);
fprintf('pendiente negativa entre v1 = %.4f y v2 = %.4f;  h(v2) = %.4f &gt; 0\n', v1, v2, ...
