    subplot(1,2,2); semilogx(w, w.^2.*real(G)); hold on;
end
Las ecuaciones KYP (§11.7).
ejemplos = { 'RLC s/(s^2+s+1)',      [0 1; -1 -1], [0; 1], [0 1],   eye(2),         0;
             '(s+3)/((s+1)(s+2))',   [0 1; -2 -3], [0; 1], [3 1],   [11 3; 3 1],    0;
             '(s+1.5)/((s+1)(s+2))', [0 1; -2 -3], [0; 1], [1.5 1], [6.5 1.5; 1.5 1], 0.5 };
for k = 1:size(ejemplos, 1)
    [nombre, A, B, C, P, ep] = ejemplos{k, :};
    M = P*A + A.'*P + ep*P;                     % debe ser -L'L &lt;= 0
    L = sqrt(max(0, -diag(M))).' + 0;           % aquí M resulta diagonal
    if norm(M - diag(diag(M))) &gt; 1e-12, L = chol(-M); end
    fprintf('%-22s eig(P) = %s  |PB - C''| = %.1e  |M + L''L| = %.1e  L = %s\n', nombre, ...
            mat2str(eig(P).', 4), norm(P*B - C.'), norm(M + L.'*L), mat2str(L, 4));
end
% el mayor eps del ejemplo SPR: PA + A'P + eps P &lt;= 0
A = [0 1; -2 -3];  P = [6.5 1.5; 1.5 1];  M0 = P*A + A.'*P;
epsmax = fzero(@(e) max(eig(M0 + e*P)), [0.01 3]);
fprintf('ejemplo SPR: eps máximo = %.4f\n', epsmax);
Dos osciladores en lazo (§11.8).
a = 1;  k = 0.5;  b = 2;
opc = odeset('RelTol', 1e-10, 'AbsTol', 1e-12);
[t, X] = ode45(@(t, x) modeloOsciladores(t, x, a, k, b), linspace(0, 40, 8001), ...
        [1.5; 0; 0; 0], opc);
V1 = a*X(:,1).^4/4 + X(:,2).^2/2;            % H1: resorte duro + masa
V2 = b*X(:,3).^2/2 + X(:,4).^2/2;            % H2: resorte lineal + masa
V  = V1 + V2;
fprintf('V(0) = %.4f   max V2 = %.4f   V(40) = %.1e\n', V(1), max(V2), V(end));
fprintf('¿V no creciente? %d    ¿V1 sube en algún momento? %d\n', all(diff(V) &lt;= 1e-10), ...
        any(diff(V1) &gt; 1e-6));
dVteo = -k*X(:,2).^2 - X(:,4).^4;            % V' = -k y1^2 - y2^4
dVnum = gradient(V, t);
fprintf('max |V''(numérica) - (-k y1^2 - y2^4)| = %.1e\n', ...
        max(abs(dVnum(3:end-2) - dVteo(3:end-2))));


El modelo, una sola función para scripts y Simulink.
function dx = modeloAgua(x, c, Q, r, vm)
% MODELOAGUA  Tanques + dinámica del replicador (sección 11.10; Ramírez-Llanos y Quijano, 2010).
%   x = [v; q]  (N volúmenes y N caudales),  c: coeficientes de descarga (N x 1)
%   v_i' = q_i - c_i sqrt(v_i)                      (Torricelli)
%   q_i' = q_i (F_i - Fbar),  F_i = r (1 - v_i/vm),  Fbar = (1/Q) sum_j q_j F_j
%   Notación del artículo -&gt; curso: x_i -&gt; q_i, f_i -&gt; F_i, Sigma_1,2 -&gt; H_1,2.
N = numel(x)/2;
v = max(x(1:N), 0);            % sqrt no está definida para v &lt; 0 (error numérico)
q = x(N+1:end);
F = r*(1 - v/vm);
Fbar = (q.'*F)/Q;
dx = [q - c(:).*sqrt(v); q.*(F - Fbar)];
end
Cambio de demanda (§11.10).
x0  = [0.1; 0.8; 0.3; 0.9; 0.6; 0.5];           % [v; q], con sum q = Q
opc = odeset('RelTol', 1e-10, 'AbsTol', 1e-12);
[t1, X1] = ode45(@(t, x) modeloAgua(x, c1, Q, r, vm), linspace(0, 40, 4001), x0, opc);
[t2, X2] = ode45(@(t, x) modeloAgua(x, c2, Q, r, vm), linspace(40, 80, 4001), ...
        X1(end,:).', opc);
[V1a, V2a] = energiaAgua(X1, c1, Q, r, vm);
[V1b, V2b] = energiaAgua(X2, c2, Q, r, vm);
t = [t1; t2];   X = [X1; X2];   V = [V1a + V2a; V1b + V2b];
fprintf('max |sum q - Q| = %.1e\n', max(abs(sum(X(:,4:6), 2) - Q)));
fprintf('¿V no creciente en cada tramo? %d %d\n', all(diff(V1a + V2a) &lt;= 1e-9), ...
        all(diff(V1b + V2b) &lt;= 1e-9));
fprintf('v(80) = %s   q(80) = %s\n', mat2str(X(end,1:3), 4), mat2str(X(end,4:6), 4));
La trampa de las caras (§11.10).
Q = 2;  r = 2;  vm = 2;  c = [0.6; 1.0; 1.4];
fprintf('tanque 3 sin caudal: se vacía en t = 2 sqrt(v3(0))/c3 = %.4f s\n', ...
        2*sqrt(0.4)/1.4);
for q30 = 10.^(-2:-2:-8)
    x0  = [0.4; 0.4; 0.4; 1 - q30/2; 1 - q30/2; q30];
    ev  = @(t, x) deal(x(6) - 0.5, 1, 1);           % q3 cruza 0.5 subiendo
    opc = odeset('RelTol', 1e-8, 'AbsTol', [1e-10*ones(5,1); 1e-3*q30], 'Events', ...
            ev);   % tolerancia a la escala de q3
    [~, ~, te] = ode45(@(t, x) modeloAgua(x, c, Q, r, vm), [0 40], x0, opc);
    fprintf('q3(0) = %.0e:  q3 llega a 0.5 en t = %.2f s\n', q30, te);
end


PD con y sin compensación de gravedad (§11.9).
m = 1;  l = 1;  g = 9.81;  bf = 0.5;  Kp = 20;  Kd = 5;  qr = pi/3;
for compensa = [true false]
    ley = @(q, dq) compensa*m*g*l*sin(q) - Kp*(q - qr) - Kd*dq;
    f = @(t, x) [x(2); (ley(x(1), x(2)) - bf*x(2) - m*g*l*sin(x(1)))/(m*l^2)];
    [t, X] = ode45(f, [0 10], [0; 0], opc);
    fprintf('compensación = %d:  q(10) = %.4f rad = %.2f°\n', compensa, X(end,1), ...
            rad2deg(X(end,1)));
end
qss = fzero(@(q) Kp*(qr - q) - m*g*l*sin(q), [0 qr]);    % equilibrio del PD solo
fprintf('PD solo: equilibrio q = %.4f rad; error = %.2f°\n', qss, rad2deg(qr - qss));
Escape en tiempo finito de una cascada (§11.9).
k = 1;  x0 = 1;  z0 = 3;                   % x0 z0 = 3 &gt; 1 + k = 2
evento = @(t, x) deal(abs(x(1)) - 1e6, 1, 0);
opc = odeset('RelTol', 1e-11, 'AbsTol', 1e-12, 'Events', evento);
[t, X, te] = ode45(@(t, x) [-x(1) + x(1)^2*x(2); -k*x(2)], [0 5], [x0; z0], opc);
% fórmula exacta: con w = 1/x, w' = w - z0 e^{-k t}  -&gt;  w = 0 en
tex = log((z0/(1 + k))/(z0/(1 + k) - 1/x0))/(1 + k);
fprintf('u = -k z: |x| llega a 1e6 en t = %.4f;  escape exacto en t = %.4f\n', te, tex);


Los modelos se construyen por código: ejecute el script y se crea, se simula y se compara con ode45.
LazoPasivo.slx: dos osciladores en la conexión estándar, con \(V_1\), \(V_2\) y \(V\) en línea.
%% crearModelo_LazoPasivo -- Construye "LazoPasivo.slx" (sección 11.8)
% Dos osciladores no lineales en la conexión estándar de Khalil (Fig. 6.11):
%   H1: x1' = x2,  x2' = -a x1^3 - k x2 + e1,  y1 = x2      (OSP y ZSO)
%   H2: x3' = x4,  x4' = -b x3 - x4^3 + e2,    y2 = x4      (OSP y ZSO)
%   e1 = u1 - y2,  e2 = u2 + y1.
% Calcula en línea V1, V2 y V = V1 + V2, los muestra en un Scope y los guarda
% en el workspace; al final compara con ode45 (modeloOsciladores.m).
% USO   1) ejecute el script (crea, simula y compara);
%       2) abra el Scope "energias": V1 y V2 suben y bajan, V solo baja;
%       3) cambie el signo del sumador e1 a '++' y vuelva a simular (trampa del signo).
clear; clc;
a = 1;  k = 0.5;  b = 2;  x0 = [1.5 0 0 0];
vars = {'a', 'k', 'b', 'x0'};
for i = 1:numel(vars), assignin('base', vars{i}, eval(vars{i})); end

mdl = 'LazoPasivo';
if bdIsLoaded(mdl), close_system(mdl, 0); end
new_system(mdl);  open_system(mdl);
blk = @(tipo, nombre, varargin) add_block(tipo, [mdl '/' nombre], varargin{:});
lin = @(desde, hasta) add_line(mdl, desde, hasta, 'autorouting', 'on');

% --- entradas externas (cero: el lazo evoluciona solo) y conexión estándar
blk('simulink/Sources/Constant', 'u1', 'Value', '0', 'Position', [20 40 50 60]);
blk('simulink/Sources/Constant', 'u2', 'Value', '0', 'Position', [520 260 550 280]);
blk('simulink/Math Operations/Sum', 'e1 = u1 - y2', 'Inputs', '+-', 'Position', [90 40 110 60]);
blk('simulink/Math Operations/Sum', 'e2 = u2 + y1', 'Inputs', '++', 'Position', [460 250 480 270]);
% --- H1
blk('simulink/Signal Routing/Mux', 'mux H1', 'Inputs', '3', 'Position', [150 20 155 90]);
blk('simulink/User-Defined Functions/Fcn', 'x2'' (H1)', 'Expr', '-a*u(1)^3 - k*u(2) + u(3)', 'Position', [180 40 300 70]);
blk('simulink/Continuous/Integrator', 'x2', 'InitialCondition', 'x0(2)', 'Position', [330 40 360 70]);
blk('simulink/Continuous/Integrator', 'x1', 'InitialCondition', 'x0(1)', 'Position', [400 100 430 130]);
% --- H2
blk('simulink/Signal Routing/Mux', 'mux H2', 'Inputs', '3', 'Position', [420 200 425 270], 'Orientation', 'left');
blk('simulink/User-Defined Functions/Fcn', 'x4'' (H2)', 'Expr', '-b*u(1) - u(2)^3 + u(3)', 'Position', [270 220 390 250], 'Orientation', 'left');
blk('simulink/Continuous/Integrator', 'x4', 'InitialCondition', 'x0(4)', 'Position', [200 220 230 250], 'Orientation', 'left');
blk('simulink/Continuous/Integrator', 'x3', 'InitialCondition', 'x0(3)', 'Position', [130 290 160 320], 'Orientation', 'left');
% --- energías
blk('simulink/Signal Routing/Mux', 'mux x', 'Inputs', '4', 'Position', [560 330 565 410]);
blk('simulink/User-Defined Functions/Fcn', 'V1', 'Expr', 'a*u(1)^4/4 + u(2)^2/2', 'Position', [600 330 700 355]);
blk('simulink/User-Defined Functions/Fcn', 'V2', 'Expr', 'b*u(3)^2/2 + u(4)^2/2', 'Position', [600 385 700 410]);
blk('simulink/Math Operations/Sum', 'V', 'Inputs', '++', 'Position', [740 360 760 380]);
blk('simulink/Signal Routing/Mux', 'mux V', 'Inputs', '3', 'Position', [790 330 795 410]);
blk('simulink/Sinks/Scope', 'energias', 'Position', [830 355 860 385]);
blk('simulink/Sinks/To Workspace', 'a workspace', 'VariableName', 'Vsim', 'SaveFormat', 'Array', 'Position', [830 420 900 440]);

lin('u1/1', 'e1 = u1 - y2/1');   lin('e1 = u1 - y2/1', 'mux H1/3');
lin('x1/1', 'mux H1/1');         lin('x2/1', 'mux H1/2');
lin('mux H1/1', 'x2'' (H1)/1');  lin('x2'' (H1)/1', 'x2/1');   lin('x2/1', 'x1/1');
lin('x2/1', 'e2 = u2 + y1/2');   lin('u2/1', 'e2 = u2 + y1/1');  lin('e2 = u2 + y1/1', 'mux H2/3');
lin('x3/1', 'mux H2/1');         lin('x4/1', 'mux H2/2');
lin('mux H2/1', 'x4'' (H2)/1');  lin('x4'' (H2)/1', 'x4/1');   lin('x4/1', 'x3/1');
lin('x4/1', 'e1 = u1 - y2/2');
lin('x1/1', 'mux x/1');  lin('x2/1', 'mux x/2');  lin('x3/1', 'mux x/3');  lin('x4/1', 'mux x/4');
lin('mux x/1', 'V1/1');  lin('mux x/1', 'V2/1');  lin('V1/1', 'V/1');  lin('V2/1', 'V/2');
lin('V1/1', 'mux V/1');  lin('V2/1', 'mux V/2');  lin('V/1', 'mux V/3');
lin('mux V/1', 'energias/1');  lin('mux V/1', 'a workspace/1');
try, Simulink.BlockDiagram.arrangeSystem(mdl); catch, end   % (R2018b o posterior)
set_param(mdl, 'StopTime', '40', 'Solver', 'ode45', 'RelTol', '1e-8', 'AbsTol', '1e-10', 'MaxStep', '0.01');
save_system(mdl);
fprintf('Modelo %s.slx creado. Simulando...\n', mdl);

% --- simular y comparar con ode45
salida = sim(mdl);
tS = salida.tout;   VS = salida.get('Vsim');
[tO, XO] = ode45(@(t, x) modeloOsciladores(t, x, a, k, b), tS, x0(:), odeset('RelTol', 1e-10, 'AbsTol', 1e-12));
VO = a*XO(:,1).^4/4 + XO(:,2).^2/2 + b*XO(:,3).^2/2 + XO(:,4).^2/2;
fprintf('max |V(Simulink) - V(ode45)| = %.1e   (esperado &lt; 1e-5)\n', max(abs(VS(:,3) - VO)));
fprintf('¿V no creciente en Simulink? %d\n', all(diff(VS(:,3)) &lt;= 1e-8));
